111	// makeProgressDispatcher returns a per-event handler that translates raw
112	// stream events into agent.GenerationProgress callbacks. PhaseDone is
113	// emitted by GenerateTextStreaming after cmd.Wait, because it needs data
114	// from the parsed final envelope (OutputTokens, DurationMs).
115	func makeProgressDispatcher(progress agent.ProgressFn) func(streamEvent) {
116		if progress == nil {
117			return func(streamEvent) {} // no-op: drain events
118		}
119		var outputTokensEstimate int
120		return func(ev streamEvent) {
121			switch {
122			case ev.Type == "system" && ev.Subtype == "status" && ev.Status == "requesting":
123				progress(agent.GenerationProgress{Phase: agent.PhaseConnecting})
124			case ev.Type == "stream_event" && ev.Event.Type == "message_start":
125				p := agent.GenerationProgress{Phase: agent.PhaseFirstToken, TTFTms: ev.TTFTms}
126				if ev.Event.Message != nil && ev.Event.Message.Usage != nil {
127					p.InputTokens = ev.Event.Message.Usage.InputTokens
128					p.CachedInputTokens = ev.Event.Message.Usage.CacheReadInputTokens
129				}
130				progress(p)
131			case ev.Type == "stream_event" && ev.Event.Type == "content_block_delta" && ev.Event.Delta != nil:
132				text := ev.Event.Delta.Text
133				if text == "" {
134					text = ev.Event.Delta.Thinking
135				}
136				outputTokensEstimate += len(text) / 4 // rough estimate: ~4 chars/token
137				progress(agent.GenerationProgress{Phase: agent.PhaseGenerating, OutputTokens: outputTokensEstimate})
138			}
139		}
