149	// looksLikeUnrecognizedFlag returns true if stderr indicates the CLI
150	// rejected one of the streaming-specific flags (older Claude CLI that
151	// doesn't support stream-json or --verbose). Requires both a rejection
152	// phrase AND a streaming flag name to avoid false-positives on unrelated
153	// errors that happen to contain "unknown option".
154	func looksLikeUnrecognizedFlag(stderr string) bool {
155		lower := strings.ToLower(stderr)
156		hasRejectPhrase := strings.Contains(lower, "unrecognized option") ||
157			strings.Contains(lower, "unknown flag") ||
158			strings.Contains(lower, "unknown option") ||
159			strings.Contains(lower, "invalid option")
160		if !hasRejectPhrase {
161			return false
162		}
163		return strings.Contains(lower, "stream-json") ||
164			strings.Contains(lower, "verbose") ||
165			strings.Contains(lower, "include-partial")
166	}
